mapper.select:
SELECT R.ROLE_CODE , R.ROLE_NAME , R.SORT_ORDER , R.DATA_STATUS , R.CREATED_BY , R.CREATED_AT , R.UPDATED_BY , R.UPDATED_AT FROM TB_ROLE R WHERE TRUE
AND R.ROLE_NAME LIKE CONCAT('%', #{roleName}, '%')
AND EXISTS ( SELECT 1 FROM TB_ROLE_PERMISSION RP WHERE RP.ROLE_CODE = R.ROLE_CODE AND RP.PERMISSION_CODE IN
#{permissionCode}
)
AND R.DATA_STATUS = #{dataStatus}
ORDER BY R.SORT_ORDER

SELECT R.ROLE_CODE , R.ROLE_NAME , R.SORT_ORDER , R.DATA_STATUS , R.CREATED_BY , R.CREATED_AT , R.UPDATED_BY , R.UPDATED_AT , RP.PERMISSION_CODE FROM TB_ROLE R LEFT JOIN TB_ROLE_PERMISSION RP ON R.ROLE_CODE = RP.ROLE_CODE WHERE TRUE
AND R.ROLE_CODE = #{roleCode}
ORDER BY R.SORT_ORDER, RP.PERMISSION_CODE

mapper.insert:
INSERT INTO TB_ROLE (
    ROLE_CODE
  , ROLE_NAME
  , DATA_STATUS
  , SORT_ORDER
  , CREATED_BY
  , UPDATED_BY
) VALUES (
    #{roleCode}
  , #{roleName}
  , #{dataStatus}
  , #{sortOrder}
  , #{author}
  , #{author}
)

INSERT INTO TB_ROLE_PERMISSION (
    ROLE_CODE
  , PERMISSION_CODE
) VALUES

(
    #{roleCode}
  , #{permissionCode}
)

mapper.update:
UPDATE TB_ROLE
   SET ROLE_NAME   = #{roleName}
     , DATA_STATUS = #{dataStatus}
     , SORT_ORDER  = #{sortOrder}
     , UPDATED_BY  = #{author}
     , UPDATED_AT  = NOW()
 WHERE ROLE_CODE   = #{roleCode}

